// bug-age repro for 8a6a8dc9d5 "Fixing decoder strip because of char boundaries".
// Strip sliced tokens by byte index, panicking inside multi-byte characters.
use tokenizers::decoders::strip::Strip;
use tokenizers::Decoder;

#[test]
fn strip_respects_char_boundaries() {
    let decoder = Strip::new(1, 0);
    let out = decoder.decode_chain(vec!["▁hello".to_string()]).unwrap();
    assert_eq!(out, vec!["hello".to_string()]);
}

// bug-age repro for 9a93c50c25 "Fix stride condition".
// with_truncation rejected stride == effective max length (<= instead of <).
use std::collections::HashMap;
use tokenizers::models::wordlevel::WordLevel;
use tokenizers::{Tokenizer, TruncationParams};

#[test]
fn stride_equal_to_max_length_is_accepted() {
    let mut vocab = HashMap::new();
    vocab.insert("<unk>".to_string(), 0u32);
    let model = WordLevel::builder().vocab(vocab).unk_token("<unk>".to_string()).build().unwrap();
    let mut tokenizer = Tokenizer::new(model);
    let params = TruncationParams { max_length: 2, stride: 2, ..Default::default() };
    assert!(tokenizer.with_truncation(Some(params)).is_ok());
}

// bug-age repro for 9b77c054ef "Fix off-by-one error in tokenizer::normalizer::Range::len".
use tokenizers::tokenizer::normalizer::Range;

#[test]
fn range_len_counts_inclusive_and_exclusive_bounds() {
    assert_eq!(Range::Original(3..=7).len(), Some(5));
    assert_eq!(Range::Original(3..7).len(), Some(4));
}

// bug-age repro for a350ec3e72 "Fix a bug in the Metaspace PreTokenizer".
// With add_prefix_space, the prefix was added before spaces were replaced, so an input
// starting with a space got a doubled "▁".
use tokenizers::pre_tokenizers::metaspace::Metaspace;
use tokenizers::{OffsetReferential, OffsetType, PreTokenizedString, PreTokenizer};

#[test]
fn leading_space_is_not_doubled() {
    let pretok = Metaspace::new('▁', true);
    let mut s = PreTokenizedString::from(" Hey friend!");
    pretok.pre_tokenize(&mut s).unwrap();
    let toks: Vec<String> = s
        .get_splits(OffsetReferential::Normalized, OffsetType::Byte)
        .into_iter()
        .map(|split| split.0.to_string())
        .collect();
    assert_eq!(toks, vec!["▁Hey".to_string(), "▁friend!".to_string()]);
}

// bug-age repro for c046da7679 "Fix stripping strings containing Unicode characters".
// strip() compared char indices against the byte length, so trailing whitespace after
// multi-byte characters was not removed.
use tokenizers::NormalizedString;

#[test]
fn strip_removes_whitespace_around_unicode() {
    let mut n = NormalizedString::from("  你好asa \n");
    n.strip();
    assert_eq!(n.get(), "你好asa");
}

// bug-age repro for fb837b4adb "Fix wordlevel encode `<unk>`".
// An unknown word got the unk id but kept its own text as the token value.
use std::collections::HashMap;
use tokenizers::models::wordlevel::WordLevel;
use tokenizers::Model;

#[test]
fn unknown_word_becomes_unk_token() {
    let mut vocab = HashMap::new();
    vocab.insert("<unk>".to_string(), 0u32);
    vocab.insert("a".to_string(), 1u32);
    let model = WordLevel::builder().vocab(vocab).unk_token("<unk>".to_string()).build().unwrap();
    let tokens = model.tokenize("c").unwrap();
    assert_eq!(tokens.len(), 1);
    assert_eq!(tokens[0].id, 0);
    assert_eq!(tokens[0].value, "<unk>");
}
